 1	/**
 2	 * Lo que `runMigrations` (async, `Bun.SQL`) y `runMigrationsSync` (sync,
 3	 * `bun:sqlite`) comparten sin diferencia entre motores: la forma de una
 4	 * migración, la validación de la lista antes de tocar la base y el DDL de la
 5	 * tabla de control. Vive aparte para que la validación sea UNA función, no
 6	 * dos copias que puedan divergir entre los dos runners.
 7	 */
 8	import type { Dialect } from './sql.ts'
 9	
10	/** Una versión de esquema, con su DDL propio por motor (no es portable). */
11	export type Migration = { version: number; statements: Record<Dialect, string[]> }
12	
13	/** El esquema de la tabla de control, común a los dos runners. */
14	export const CONTROL_TABLE_DDL = (table: string): string =>
15	  `CREATE TABLE IF NOT EXISTS ${table} (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL)`
16	
17	/**
18	 * El nombre de la tabla de control va interpolado en el DDL (`CREATE TABLE
19	 * IF NOT EXISTS <table>`): sólo se acepta si es un identificador simple, para
20	 * no abrir una inyección por ese nombre.
21	 */
22	const TABLE_NAME_PATTERN = /^[a-z_][a-z0-9_]*$/
23	
24	export function assertValidTable(table: string): void {
25	  if (!TABLE_NAME_PATTERN.test(table)) {
26	    throw new Error(`invalid migrations table name '${table}': expected a simple identifier matching ${TABLE_NAME_PATTERN}`)
27	  }
28	}
29	
30	/**
31	 * Enteros positivos, sin repetir y en orden ascendente — el orden en que se
32	 * aplican es el orden de la lista, así que una lista desordenada aplicaría
33	 * fuera de secuencia sin decirlo.
34	 */
35	export function assertValidVersions(migrations: readonly Migration[]): void {
36	  const seen = new Set<number>()
37	  for (const { version } of migrations) {
38	    if (!Number.isInteger(version) || version <= 0) {
39	      throw new Error(`invalid migration version ${version}: expected a positive integer`)
40	    }
41	    if (seen.has(version)) throw new Error(`duplicate migration version ${version}`)
42	    seen.add(version)
43	  }
44	  for (let i = 1; i < migrations.length; i++) {
45	    const previous = migrations[i - 1]!.version
46	    const current = migrations[i]!.version
47	    if (current < previous) {
48	      throw new Error(`migrations out of order: version ${current} follows version ${previous}, expected ascending order`)
49	    }
50	  }
51	}
52	
53	/**
54	 * Rehúsa si la tabla de control declara una versión que la lista ya no
55	 * trae — eso es una base más nueva que el código que la abre.
56	 */
57	export function assertNoNewerDatabase(table: string, applied: ReadonlySet<number>, migrations: readonly Migration[]): void {
58	  const declared = new Set(migrations.map(migration => migration.version))
59	  for (const version of applied) {
60	    if (!declared.has(version)) {
61	      throw new Error(
62	        `migrations table '${table}' has version ${version} applied, which is no longer declared in this migration list (database is newer than code)`,
63	      )
64	    }
65	  }
66	}
67	
68	/** El mensaje de una migración que falla, con su versión y causa — igual en los dos runners. */
69	export function migrationFailedError(version: number, cause: unknown): Error {
70	  return new Error(`migration version ${version} failed: ${cause instanceof Error ? cause.message : String(cause)}`, { cause })
71	}

