  1	/**
  2	 * El contrato de `migrationRunnerContract.ts`, aplicado a las dos
  3	 * implementaciones que `@thyrox/store` ofrece hoy: `runMigrationsSync`
  4	 * (sync, `bun:sqlite`) y `runMigrations` (async, `Bun.SQL`) sobre SQLite y,
  5	 * si `THYROX_TEST_POSTGRES_URL` está declarada, sobre PostgreSQL — misma
  6	 * forma de tres ramas que `contract.test.ts` ya usa para `sql.ts`.
  7	 */
  8	import { Database } from 'bun:sqlite'
  9	import type { SQL } from 'bun'
 10	import { describe, test } from 'bun:test'
 11	
 12	import { openByUrl } from '../sql.ts'
 13	import { runMigrations } from '../migrations.ts'
 14	import { runMigrationsSync } from '../migrationsSync.ts'
 15	import { resolvePostgresTestUrl, withDisposableSchema } from '../testing/postgresTestSchema.ts'
 16	import { defineMigrationRunnerContract, type MigrationRunnerEngine } from './migrationRunnerContract.ts'
 17	
 18	function syncSqliteEngine(db: Database): MigrationRunnerEngine {
 19	  return {
 20	    async run(options) {
 21	      return runMigrationsSync(db, options)
 22	    },
 23	    async tableExists(name) {
 24	      return (db.query(`SELECT name FROM sqlite_master WHERE type='table' AND name = ?`).all(name) as { name: string }[]).length > 0
 25	    },
 26	    async controlColumns(table) {
 27	      return db.query(`PRAGMA table_info(${table})`).all() as { name: string; notnull: number; pk: number }[]
 28	    },
 29	    async controlVersions(table) {
 30	      return (db.query(`SELECT version FROM ${table} ORDER BY version`).all() as { version: number }[]).map(row => Number(row.version))
 31	    },
 32	    async seqLabels() {
 33	      return (db.query(`SELECT label FROM seq ORDER BY id`).all() as { label: string }[]).map(row => row.label)
 34	    },
 35	  }
 36	}
 37	
 38	function asyncSqliteEngine(sql: SQL): MigrationRunnerEngine {
 39	  return {
 40	    async run(options) {
 41	      return runMigrations(sql, 'sqlite', options)
 42	    },
 43	    async tableExists(name) {
 44	      const rows = (await sql.unsafe(`SELECT name FROM sqlite_master WHERE type='table' AND name = $1`, [name])) as { name: string }[]
 45	      return rows.length > 0
 46	    },
 47	    async controlColumns(table) {
 48	      return (await sql.unsafe(`PRAGMA table_info(${table})`)) as { name: string; notnull: number; pk: number }[]
 49	    },
 50	    async controlVersions(table) {
 51	      const rows = (await sql.unsafe(`SELECT version FROM ${table} ORDER BY version`)) as { version: number }[]
 52	      return rows.map(row => Number(row.version))
 53	    },
 54	    async seqLabels() {
 55	      const rows = (await sql.unsafe(`SELECT label FROM seq ORDER BY id`)) as { label: string }[]
 56	      return rows.map(row => row.label)
 57	    },
 58	  }
 59	}
 60	
 61	/**
 62	 * `information_schema.columns` no filtra por `search_path`: sin
 63	 * `table_schema = current_schema()` vería también las tablas homónimas de
 64	 * otro esquema de prueba desechable.
 65	 */
 66	function asyncPostgresEngine(sql: SQL): MigrationRunnerEngine {
 67	  return {
 68	    async run(options) {
 69	      return runMigrations(sql, 'postgres', options)
 70	    },
 71	    async tableExists(name) {
 72	      const [row] = (await sql`SELECT to_regclass(${name}) IS NOT NULL AS found`) as { found: boolean }[]
 73	      return Boolean(row?.found)
 74	    },
 75	    async controlColumns(table) {
 76	      const rows = (await sql`
 77	        SELECT c.column_name AS name,
 78	               (c.is_nullable = 'NO')::int AS notnull,
 79	               (pk.column_name IS NOT NULL)::int AS pk
 80	        FROM information_schema.columns c
 81	        LEFT JOIN (
 82	          SELECT kcu.column_name
 83	          FROM information_schema.table_constraints tc
 84	          JOIN information_schema.key_column_usage kcu
 85	            ON kcu.constraint_name = tc.constraint_name AND kcu.table_name = tc.table_name
 86	          WHERE tc.table_name = ${table} AND tc.constraint_type = 'PRIMARY KEY'
 87	        ) pk ON pk.column_name = c.column_name
 88	        WHERE c.table_name = ${table} AND c.table_schema = current_schema()
 89	      `) as { name: string; notnull: number; pk: number }[]
 90	      return rows.map(row => ({ name: row.name, notnull: Number(row.notnull), pk: Number(row.pk) }))
 91	    },
 92	    async controlVersions(table) {
 93	      const rows = (await sql.unsafe(`SELECT version FROM ${table} ORDER BY version`)) as { version: number | string }[]
 94	      return rows.map(row => Number(row.version))
 95	    },
 96	    async seqLabels() {
 97	      const rows = (await sql`SELECT label FROM seq ORDER BY id`) as { label: string }[]
 98	      return rows.map(row => row.label)
 99	    },
100	  }
101	}
102	
103	defineMigrationRunnerContract({
104	  name: 'sync — bun:sqlite (runMigrationsSync)',
105	  async withEngine(body) {
106	    const db = new Database(':memory:')
107	    try {
108	      await body(syncSqliteEngine(db))
109	    } finally {
110	      db.close()
111	    }
112	  },
113	})
114	
115	defineMigrationRunnerContract({
116	  name: 'async — sqlite vía Bun.SQL (runMigrations)',
117	  async withEngine(body) {
118	    const { sql } = openByUrl('sqlite://:memory:')
119	    try {
120	      await body(asyncSqliteEngine(sql))
121	    } finally {
122	      await sql.close()
123	    }
124	  },
125	})
126	
127	let postgresUrl: string | null = null
128	let postgresUrlError: Error | null = null
129	try {
130	  postgresUrl = resolvePostgresTestUrl(process.env)
131	} catch (e) {
132	  postgresUrlError = e instanceof Error ? e : new Error(String(e))
133	}
134	
135	if (postgresUrlError) {
136	  // La variable está declarada pero mal escrita: eso no es "no medido", es un
137	  // dato roto, y se dice en rojo en vez de tratarlo como ausencia silenciosa.
138	  const error = postgresUrlError
139	  describe('contrato del runner de migraciones — async — postgres', () => {
140	    test(`THYROX_TEST_POSTGRES_URL inválida: ${error.message}`, () => {
141	      throw error
142	    })
143	  })
144	} else if (postgresUrl) {
145	  const url = postgresUrl
146	  defineMigrationRunnerContract({
147	    name: 'async — postgres vía Bun.SQL (runMigrations)',
148	    async withEngine(body) {
149	      await withDisposableSchema(url, async sql => body(asyncPostgresEngine(sql)))
150	    },
151	  })
152	} else if (process.env.THYROX_TEST_REQUIRE_POSTGRES === '1') {
153	  describe('contrato del runner de migraciones — async — postgres', () => {
154	    test('THYROX_TEST_REQUIRE_POSTGRES=1 exige el contrato en postgres, y THYROX_TEST_POSTGRES_URL no está declarada', () => {
155	      throw new Error('THYROX_TEST_REQUIRE_POSTGRES=1 exige THYROX_TEST_POSTGRES_URL, que no está declarada')
156	    })
157	  })
158	} else {
159	  describe('contrato del runner de migraciones — async — postgres', () => {
160	    test.todo('NO MEDIDO: declara THYROX_TEST_POSTGRES_URL para correr el contrato en postgres', () => {})
161	  })
162	}

